  const data = await res.json();

  if (!data.ok) {
    throw new Error(`Slack API error: ${data.error}`);
  }

  return {
    messages: data.messages,
    next_cursor: data.response_metadata?.next_cursor || null,
    has_more: Boolean(data.has_more),
  };
}
```

## 3. Define an output schema and register the tool

```typescript
const ListSlackMessagesOutputSchema = z.object({
  messages: z.array(z.object({
    ts: z.string(),
    user: z.string().optional(),
    text: z.string(),
  })),
  next_cursor: z.string().nullable()
    .describe("Pass this back as the 'cursor' input to fetch the next page. Null if no more messages."),
  has_more: z.boolean(),
});

server.registerTool(
  "slack_list_messages",
  {
    title: "List Slack Messages",
    description:
      "List messages from a Slack channel, newest first. Supports cursor-based pagination — " +
      "call again with the returned next_cursor to fetch subsequent pages.",
    inputSchema: ListSlackMessagesSchema.shape,
    outputSchema: ListSlackMessagesOutputSchema.shape,
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },
