    .min(1)
    .max(200)
    .default(50)
    .describe("Number of messages to return per page (1-200). Example: 50"),
  cursor: z
    .string()
    .optional()
    .describe(
      "Pagination cursor from a previous call's `next_cursor` field. Omit to fetch the first page."
    ),
});
```

## 2. Call the Slack API with the cursor and return the next one

```typescript
server.registerTool(
  "slack_list_messages",
  {
    description:
      "List messages from a Slack channel, paginated via cursor. Returns messages and a next_cursor for the following page (empty if no more results).",
    inputSchema: ListMessagesInput,
    outputSchema: z.object({
      messages: z.array(z.any()),
      next_cursor: z.string().optional(),
      has_more: z.boolean(),
    }),
    annotations: {
      readOnlyHint: true,
      destructiveHint: false,
      idempotentHint: true,
      openWorldHint: true,
    },
  },
  async ({ channel, limit, cursor }) => {
    const params = new URLSearchParams({
      channel,
      limit: String(limit),
      ...(cursor ? { cursor } : {}),
    });

    const res = await fetch(
      `https://slack.com/api/conversations.history?${params}`,
      {
        headers: { Authorization: `Bearer ${process.env.SLACK_BOT_TOKEN}` },
      }
    );
    const data = await res.json();

    if (!data.ok) {
      throw new Error(
        `Slack API error: ${data.error}. Check the channel ID and that your bot token has 'channels:history' scope.`
      );
    }

    const nextCursor = data.response_metadata?.next_cursor || undefined;

    return {
      structuredContent: {
        messages: data.messages,
        next_cursor: nextCursor,
        has_more: Boolean(nextCursor),
      },
      content: [
        {
          type: "text",
          text: JSON.stringify(
            {
              messages: data.messages,
              next_cursor: nextCursor,
              has_more: Boolean(nextCursor),
            },
            null,
            2
          ),
        },
      ],
    };
  }
);
```

## Key points

- **Opaque cursor**: Treat Slack's `next_cursor` as an opaque string—don't parse or construct it yourself, just pass it back on the next call.
