## 5. Shared client + error handling (`src/client.ts` skeleton)

Since this is going to call Airtable's REST API repeatedly across many tools, put one wrapper around `fetch` here that every tool in `tools/*.ts` calls through — this is where the shared error-mapping helper lives (401 → invalid/missing token, 404 → base or table not found, 429 → rate limited, timeout → retry), so no individual tool ever lets a raw HTTP error or traceback reach the caller.

```typescript
const AIRTABLE_API_BASE = "https://api.airtable.com/v0";

export class AirtableError extends Error {}

export async function airtableRequest(path: string, init?: RequestInit) {
  const apiKey = process.env.AIRTABLE_API_KEY;
  if (!apiKey) {
    throw new AirtableError(
      "Invalid or missing API key. Set AIRTABLE_API_KEY to a valid Airtable Personal Access Token."
    );
  }

  let res: Response;
  try {
    res = await fetch(`${AIRTABLE_API_BASE}${path}`, {
      ...init,
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        ...init?.headers,
      },
    });
  } catch {
    throw new AirtableError("Request timed out or network error occurred. Retry the request.");
  }

  if (res.status === 401) {
    throw new AirtableError("Invalid or missing API key. Check AIRTABLE_API_KEY.");
  }
  if (res.status === 404) {
    throw new AirtableError('Resource not found. Check the base/table/record ID, or try listing available bases first.');
  }
  if (res.status === 429) {
    throw new AirtableError("Rate limited by Airtable. Wait a moment and retry.");
  }
  if (!res.ok) {
    throw new AirtableError(`Airtable API error (${res.status}): ${await res.text()}`);
  }

  return res.json();
}
```

Every tool (`bases.ts`, `records.ts`) imports `airtableRequest` — none should call `fetch` or `raise_for_status`-style checks directly.

## 6. Entry point shape (`src/index.ts`)

```typescript
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
