      "value from a previous response as `cursor` to fetch the next page.",
    inputSchema: {
      channel: z.string().describe("Channel ID, e.g. C0123456789"),
      limit: z
        .number()
        .int()
        .min(1)
        .max(200)
        .default(50)
        .describe("Max messages to return per page (1-200)"),
      cursor: z
        .string()
        .optional()
        .describe("Pagination cursor from a previous response's next_cursor"),
    },
    outputSchema: {
      messages: z.array(
        z.object({
          ts: z.string(),
          user: z.string().optional(),
          text: z.string(),
        })
      ),
      next_cursor: z
        .string()
        .optional()
        .describe("Pass this as `cursor` to get the next page; absent if no more results"),
      has_more: z.boolean(),
    },
    annotations: {
      readOnlyHint: true,
      idempotentHint: true,
      openWorldHint: true,
    },
  },
  async ({ channel, limit, cursor }) => {
    try {
      const result = await slack.conversations.history({
        channel,
        limit,
        cursor,
      });

      const messages = (result.messages ?? []).map((m) => ({
        ts: m.ts ?? "",
        user: m.user,
        text: m.text ?? "",
      }));

      const next_cursor = result.response_metadata?.next_cursor || undefined;

      const structuredContent = {
        messages,
        next_cursor,
        has_more: Boolean(next_cursor),
      };

      return {
        content: [
          {
            type: "text",
            text:
              `Returned ${messages.length} message(s).` +
              (next_cursor
                ? ` More available — call again with cursor="${next_cursor}".`
                : " No more results."),
          },
        ],
        structuredContent,
      };
    } catch (err: any) {
      return {
        isError: true,
        content: [
          {
            type: "text",
            text: `Failed to list messages for channel "${channel}": ${
              err?.data?.error ?? err.message
            }. Check that the channel ID is correct and the bot is a member of the channel.`,
          },
        ],
      };
    }
  }
);
```

Key points:
- `cursor` is an opaque, optional string input — never construct it yourself, just forward what Slack returned.
- Read `next_cursor` from `result.response_metadata.next_cursor`; treat an empty string as "no more pages" (Slack returns `""` rather than omitting the field).
- Expose `next_cursor` and `has_more` in `structuredContent` so the calling LLM/agent can decide whether to page further without re-parsing prose.
- Cap `limit` (Slack's `conversations.history` max is 999, but 200 keeps responses small) and default it so agents don't have to guess.
- Keep the tool `readOnlyHint`/`idempotentHint` true since paginating history doesn't mutate anything.

