```typescript
import { z } from "zod";
import { WebClient } from "@slack/web-api";

const slack = new WebClient(process.env.SLACK_BOT_TOKEN);

server.registerTool(
  "slack_list_messages",
  {
    description:
      "List messages from a Slack channel, newest first. Supports cursor-based pagination: " +
      "call again with the returned `next_cursor` to fetch the next page.",
    inputSchema: {
      channel: z.string().describe("Channel ID, e.g. C0123ABCXYZ"),
      limit: z
        .number()
        .int()
        .min(1)
        .max(200)
        .default(50)
        .describe("Max messages to return per page (1-200, default 50)"),
      cursor: z
        .string()
        .optional()
        .describe(
          "Pagination cursor from a previous call's `next_cursor`. Omit to fetch the first page."
        ),
    },
    outputSchema: {
      messages: z.array(
        z.object({
          ts: z.string(),
          user: z.string().optional(),
          text: z.string(),
        })
      ),
      next_cursor: z
        .string()
        .optional()
        .describe("Pass this as `cursor` to fetch the next page. Absent when no more pages."),
    },
    annotations: {
      readOnlyHint: true,
      destructiveHint: false,
      idempotentHint: true,
      openWorldHint: true,
    },
  },
  async ({ channel, limit, cursor }) => {
    try {
      const res = await slack.conversations.history({
        channel,
        limit,
        cursor,
      });

      const messages = (res.messages ?? []).map((m) => ({
        ts: m.ts!,
        user: m.user,
        text: m.text ?? "",
      }));

      const next_cursor = res.response_metadata?.next_cursor || undefined;

      return {
        content: [
          {
            type: "text",
            text:
              messages.map((m) => `[${m.ts}] ${m.user ?? "unknown"}: ${m.text}`).join("\n") ||
              "No messages found.",
          },
        ],
        structuredContent: { messages, next_cursor },
      };
    } catch (err: any) {
      const code = err?.data?.error;
      let hint = "";
      if (code === "invalid_cursor") {
        hint = " The `cursor` value is invalid or expired — omit it to restart from the first page.";
      } else if (code === "channel_not_found") {
        hint = " Double-check the channel ID; the bot must also be a member of the channel.";
      }
      throw new Error(`Slack API error (${code ?? "unknown"}): ${err.message}.${hint}`);
    }
  }
);
```

Key points:

- Slack's cursor is opaque — don't parse or construct it yourself, just pass through whatever `response_metadata.next_cursor` returned last time.
- Only include `next_cursor` in `structuredContent` when Slack actually returns one; its absence is the pagination-complete signal, so avoid emitting an empty string.
- `conversations.history` returns newest-first; if the agent needs to page forward in time instead of backward, use `oldest`/`latest` timestamp bounds instead of `cursor`.
- Keep `limit` capped (e.g. 200) so a single page can't blow up context — let the agent page rather than requesting huge batches.
